--

CREATE TABLE `employee_daily_schedule_cache` (
  `id` int(11) NOT NULL,
  `employee_id` int(11) NOT NULL,
  `schedule_date` date NOT NULL,
  `work_schedule_id` int(11) DEFAULT NULL,
  `is_rest_day` tinyint(1) DEFAULT 0,
  `is_holiday` tinyint(1) DEFAULT 0,
  `source` varchar(50) NOT NULL,
  `source_id` int(11) DEFAULT NULL,
  `schedule_name` varchar(100) DEFAULT NULL,
  `time_in` time DEFAULT NULL,
  `time_out` time DEFAULT NULL,
  `holiday_name` varchar(200) DEFAULT NULL,
  `holiday_type` enum('regular','special_non_working','special_working') DEFAULT NULL,
  `created_at` timestamp NOT NULL DEFAULT current_timestamp(),
  `updated_at` timestamp NOT NULL DEFAULT current_timestamp() ON UPDATE current_timestamp()
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_general_ci;

